-- CargoSync AI — Database Seed Script
-- Generated deterministically by backend/scripts/generate_seed_sql.py
-- Supports both DEMO and NETWORK scenarios with completely realistic synthetic names.

-- 1. OPERATORS
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, updated_at = NOW();

-- 2. DEPOTS
ON CONFLICT (id) DO UPDATE SET operator_id=EXCLUDED.operator_id, scenario=EXCLUDED.scenario, name=EXCLUDED.name, address=EXCLUDED.address, location=EXCLUDED.location;

-- 3. VEHICLES
ON CONFLICT (id) DO UPDATE SET operator_id=EXCLUDED.operator_id, scenario=EXCLUDED.scenario, reference_number=EXCLUDED.reference_number, vehicle_type=EXCLUDED.vehicle_type, capacity_kg=EXCLUDED.capacity_kg, status=EXCLUDED.status, depot_id=EXCLUDED.depot_id;

-- 4. ORDERS
ON CONFLICT (id) DO UPDATE SET operator_id=EXCLUDED.operator_id, scenario=EXCLUDED.scenario, reference_number=EXCLUDED.reference_number, origin_depot_id=EXCLUDED.origin_depot_id, destination_location=EXCLUDED.destination_location, weight_kg=EXCLUDED.weight_kg, status=EXCLUDED.status, pickup_window_start=EXCLUDED.pickup_window_start, pickup_window_end=EXCLUDED.pickup_window_end, delivery_window_start=EXCLUDED.delivery_window_start, delivery_window_end=EXCLUDED.delivery_window_end;

-- 5. RETURN LOADS
ON CONFLICT (id) DO UPDATE SET operator_id=EXCLUDED.operator_id, scenario=EXCLUDED.scenario, reference_number=EXCLUDED.reference_number, pickup_location=EXCLUDED.pickup_location, delivery_location=EXCLUDED.delivery_location, weight_kg=EXCLUDED.weight_kg, status=EXCLUDED.status, pickup_window_start=EXCLUDED.pickup_window_start, pickup_window_end=EXCLUDED.pickup_window_end, delivery_window_start=EXCLUDED.delivery_window_start, delivery_window_end=EXCLUDED.delivery_window_end;

-- 6. PROFILES (Authentication/Authorization mapping)
